
BEGIN;
CREATE TABLE IF NOT EXISTS staging.task216_imf_bop_current_account_observation (
    observation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pipeline_run_id uuid NOT NULL REFERENCES meta.pipeline_run(pipeline_run_id), source_id uuid NOT NULL REFERENCES meta.source(source_id), dataset_release_id uuid REFERENCES meta.dataset_release(dataset_release_id), territory_code text NOT NULL, territory_label text NOT NULL, indicator_code text NOT NULL, indicator_name text NOT NULL, provider_period_code text NOT NULL, period_year integer NOT NULL, value numeric, unit_code text NOT NULL, unit_label text NOT NULL, decimal_precision integer, observation_status text NOT NULL, attribute_hash text NOT NULL, attributes jsonb NOT NULL, source_payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT uq_staging_task216_imf_bop_natural UNIQUE (pipeline_run_id, territory_code, indicator_code, provider_period_code, unit_code, attribute_hash)
);
CREATE TEMP TABLE _task216_rows (territory_code text, territory_label text, indicator_code text, indicator_name text, provider_period_code text, period_year integer, value numeric, unit_code text, unit_label text, decimal_precision integer, observation_status text, attribute_hash text, attributes jsonb, source_payload jsonb) ON COMMIT DROP;
CREATE TEMP TABLE _source_row (source_id uuid) ON COMMIT DROP;
CREATE TEMP TABLE _release_row (dataset_release_id uuid) ON COMMIT DROP;
CREATE TEMP TABLE _run_row (pipeline_run_id uuid) ON COMMIT DROP;
VALUES ('IMF_SDMX_BOP_API_V1', 'International Monetary Fund SDMX BOP API', 'https://data.imf.org/', 'IMF public SDMX BOP API')
ON CONFLICT (source_code) DO UPDATE SET source_name=EXCLUDED.source_name, source_home_url=EXCLUDED.source_home_url;
SELECT source_id, 'IMF:BOP', 'imf-bop-asof-20260711t231424302015100z', NULL, 'https://api.imf.org/external/sdmx/2.1/dataflow/all/BOP/latest?references=all', 'data/processed/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-manifest.json', '57ae31ccba46c7d891f34991a28f76ea4b58af64da4e0ebcf5fe4ede4c7aa925', '{"candidate_cell_count": 16050, "explicit_missing_value_count": 875, "observed_value_count": 13600, "release_identity_basis": "provider dataset UPDATE_DATE/PUBLICATION_DATE/Prepared evidence", "task": "TASK-216", "whole_series_absence_count": 105}'::jsonb FROM _source_row
ON CONFLICT (source_id, provider_dataset_code, release_key) DO UPDATE SET source_url=EXCLUDED.source_url, raw_artifact_path=EXCLUDED.raw_artifact_path, raw_sha256=EXCLUDED.raw_sha256, metadata=EXCLUDED.metadata;
SELECT 'task-216-imf-bop-current-account-phase2', s.source_id, r.dataset_release_id, 'imf_bop_current_account_phase2_campaign', now(), 'succeeded', '{"accounting_entry": "NETCD_T", "endPeriod": "2024", "indicators": ["CAB", "G", "S", "IN1", "IN2"], "startPeriod": "2010", "task": "TASK-216"}'::jsonb, '{"manifest_path": "data/processed/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-manifest.json", "normalized_path": "data/processed/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-normalized.json", "raw_paths": ["data/raw/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-values-chunk-01.xml", "data/raw/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-values-chunk-02.xml", "data/raw/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-values-chunk-03.xml", "data/raw/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-values-chunk-04.xml", "data/raw/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-values-chunk-05.xml", "data/raw/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-values-chunk-06.xml", "data/raw/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-values-chunk-07.xml", "data/raw/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-values-chunk-08.xml", "data/raw/task216_imf_bop_phase2_campaign/active/task-216-imf-bop-values-chunk-09.xml"]}'::jsonb FROM _source_row s CROSS JOIN _release_row r
ON CONFLICT (run_key) DO UPDATE SET finished_at=EXCLUDED.finished_at, status=EXCLUDED.status, input_parameters=EXCLUDED.input_parameters, artifact_manifest=EXCLUDED.artifact_manifest;
SELECT _run_row.pipeline_run_id, _source_row.source_id, _release_row.dataset_release_id, r.* FROM _task216_rows r CROSS JOIN _run_row CROSS JOIN _source_row CROSS JOIN _release_row
ON CONFLICT (pipeline_run_id, territory_code, indicator_code, provider_period_code, unit_code, attribute_hash) DO UPDATE SET value=EXCLUDED.value, observation_status=EXCLUDED.observation_status, attributes=EXCLUDED.attributes, source_payload=EXCLUDED.source_payload;
SELECT DISTINCT s.source_id, indicator_code, indicator_name, 'IMF BOP current-account component source-scoped scalar indicator preserving accounting entry, unit, scale, and frequency', 'External Sector / Balance of Payments' FROM _task216_rows CROSS JOIN _source_row s
ON CONFLICT (source_id, source_indicator_code) DO UPDATE SET indicator_name=EXCLUDED.indicator_name, description=EXCLUDED.description, topic=EXCLUDED.topic;
SELECT DISTINCT 'A', period_year, make_date(period_year,1,1), make_date(period_year,12,31), provider_period_code FROM _task216_rows
ON CONFLICT (frequency, period_start_date, period_end_date) DO UPDATE SET period_year=EXCLUDED.period_year, period_label=EXCLUDED.period_label;
SELECT DISTINCT attribute_hash, attributes FROM _task216_rows ON CONFLICT (attribute_hash) DO UPDATE SET attributes=EXCLUDED.attributes;
DELETE FROM curated.fact_observation f USING _source_row s, _run_row pr WHERE f.source_id=s.source_id AND f.pipeline_run_id=pr.pipeline_run_id;
SELECT s.source_id, rel.dataset_release_id, pr.pipeline_run_id, i.indicator_id, t.territory_id, p.period_id, u.unit_id, a.attribute_set_id, r.value, CURRENT_DATE, CASE WHEN r.observation_status='missing' THEN 'missing' ELSE 'observed' END
FROM _task216_rows r CROSS JOIN _source_row s CROSS JOIN _release_row rel CROSS JOIN _run_row pr
JOIN curated.dim_indicator i ON i.source_id=s.source_id AND i.source_indicator_code=r.indicator_code
JOIN curated.dim_territory t ON t.iso3_code=r.territory_code
JOIN curated.dim_period p ON p.period_year=r.period_year AND p.frequency='A'
JOIN curated.dim_unit u ON u.unit_code=r.unit_code
JOIN curated.dim_attribute_set a ON a.attribute_hash=r.attribute_hash
ON CONFLICT (source_id, indicator_id, territory_id, period_id, unit_id, attribute_set_id, as_of_date) DO UPDATE SET value=EXCLUDED.value, observation_status=EXCLUDED.observation_status, dataset_release_id=EXCLUDED.dataset_release_id, pipeline_run_id=EXCLUDED.pipeline_run_id;
SELECT pipeline_run_id, 'task216_candidate_reconciliation', CASE WHEN (SELECT count(*) FROM _task216_rows)=14475 THEN 'pass' ELSE 'fail' END, (SELECT count(*) FROM _task216_rows), 14475, '{"candidate_cell_count": 16050, "explicit_missing_value_count": 875, "observed_value_count": 13600, "release_identity_basis": "provider dataset UPDATE_DATE/PUBLICATION_DATE/Prepared evidence", "task": "TASK-216", "whole_series_absence_count": 105}'::jsonb FROM _run_row
UNION ALL SELECT pipeline_run_id, 'task216_observed_missing_reconciliation', CASE WHEN (SELECT count(*) FILTER (WHERE observation_status='observed') FROM _task216_rows)=13600 AND (SELECT count(*) FILTER (WHERE observation_status='missing') FROM _task216_rows)=875 THEN 'pass' ELSE 'fail' END, (SELECT count(*) FROM _task216_rows), 14475, '{"candidate_cell_count": 16050, "explicit_missing_value_count": 875, "observed_value_count": 13600, "release_identity_basis": "provider dataset UPDATE_DATE/PUBLICATION_DATE/Prepared evidence", "task": "TASK-216", "whole_series_absence_count": 105}'::jsonb FROM _run_row;
COMMIT;
